        submitSign(actorUuid, actorName, worldId, x, y, z, joinedLines);
    }

    /**
     * Convenience for {@code PlayerJoinEvent}. Coords are ignored; pass {@code 0,0,0}.
     *
     * @param actorUuid joining player UUID
