        s.add(DROWN);
        s.add(SUFFOCATE);
        s.add(MAGIC);
        s.add(ZOMBIE);
        s.add(SKELETON);
        s.add(ENDERMAN);
        s.add(EXPLOSION);
        s.add(FLUID);
        s.add(UNKNOWN);
